1	export interface McpAuthClientOptions {
2		authURL: string;
3		resource?: string;
4		allowedOrigin?: string;
5		fetch?: typeof globalThis.fetch;
6	}
7	
8	export interface McpSession {
9		accessToken: string;
10		refreshToken: string;
11		accessTokenExpiresAt: string;
12		refreshTokenExpiresAt: string;
13		clientId: string;
14		userId: string;
15		scopes: string;
16	}
17	
18	interface OAuthDiscoveryMetadata {
19		issuer: string;
20		authorization_endpoint: string;
21		token_endpoint: string;
22		registration_endpoint?: string;
23		jwks_uri?: string;
24		scopes_supported?: string[];
25		response_types_supported?: string[];
26		grant_types_supported?: string[];
27		token_endpoint_auth_methods_supported?: string[];
28		code_challenge_methods_supported?: string[];
29		[key: string]: unknown;
30	}
31	
32	interface NodeLikeRequest {
33		headers: Record<string, string | string[] | undefined> & {
34			get?: (name: string) => string | undefined;
35			authorization?: string;
36		};
37		get?: (name: string) => string | undefined;
38		mcpSession?: McpSession;
39	}
40	
41	interface NodeLikeResponse {
42		set?: (name: string, value: string) => void;
43		setHeader?: (name: string, value: string) => void;
44		status?: (code: number) => { json: (body: unknown) => void };
45		writeHead?: (code: number, headers: Record<string, string>) => void;
46		end?: (body: string) => void;
47	}
48	
49	export interface McpAuthClient {
50		verifyToken: (token: string) => Promise<McpSession | null>;
51		handler: (
52			fn: (req: Request, session: McpSession) => Response | Promise<Response>,
53		) => (req: Request) => Promise<Response>;
54		discoveryHandler: () => (req: Request) => Promise<Response>;
55		protectedResourceHandler: (
56			serverURL: string,
57		) => (req: Request) => Promise<Response>;
58		middleware: () => (
59			req: NodeLikeRequest,
60			res: NodeLikeResponse,
61			next: () => void,
62		) => Promise<void>;
63		authURL: string;
64	}
65	
66	function buildCorsHeaders(
67		authURL: string,
68		allowedOrigin?: string,
69	): Record<string, string> {
70		let origin: string;
71		if (allowedOrigin) {
72			origin = allowedOrigin;
73		} else {
74			try {
75				origin = new URL(authURL).origin;
76			} catch {
77				origin = authURL;
78			}
79		}
80		return {
81			"Access-Control-Allow-Origin": origin,
82			"Access-Control-Allow-Methods": "GET, POST, OPTIONS",
83			"Access-Control-Allow-Headers": "Content-Type, Authorization",
84			"Access-Control-Max-Age": "86400",
85		};
86	}
87	
88	function makeWWWAuthenticate(authURL: string, resource?: string): string {
89		const resourceMetadataURL = resource
90			? `${resource}/.well-known/oauth-protected-resource`
91			: `${authURL}/.well-known/oauth-protected-resource`;
92		return `Bearer resource_metadata="${resourceMetadataURL}"`;
93	}
94	
95	function make401Response(authURL: string, resource?: string): Response {
96		const wwwAuth = makeWWWAuthenticate(authURL, resource);
97		return Response.json(
98			{
99				jsonrpc: "2.0",
100				error: {
101					code: -32000,
102					message: "Unauthorized: Authentication required",
103					"www-authenticate": wwwAuth,
104				},
105				id: null,
106			},
107			{
108				status: 401,
109				headers: {
110					"WWW-Authenticate": wwwAuth,
111				},
112			},
113		);
114	}
115	
116	function send401Node(
117		res: NodeLikeResponse,
118		wwwAuth: string,
119		message: string,
120	): void {
121		const body = JSON.stringify({
122			jsonrpc: "2.0",
123			error: { code: -32000, message },
124			id: null,
125		});
126	
127		if (typeof res.set === "function") {
128			res.set("WWW-Authenticate", wwwAuth);
129			res.status?.(401).json(JSON.parse(body));
130		} else if (typeof res.writeHead === "function") {
131			res.writeHead(401, {
132				"Content-Type": "application/json",
133				"WWW-Authenticate": wwwAuth,
134			});
135			res.end?.(body);
136		}
137	}
138	
139	export function createMcpAuthClient(
140		options: McpAuthClientOptions,
141	): McpAuthClient {
142		const authURL = options.authURL.endsWith("/")
143			? options.authURL.slice(0, -1)
144			: options.authURL;
145		const fetchFn = options.fetch ?? globalThis.fetch;
146		const corsHeaders = buildCorsHeaders(authURL, options.allowedOrigin);
147	
148		const verifyToken = async (token: string): Promise<McpSession | null> => {
149			try {
150				const response = await fetchFn(`${authURL}/mcp/get-session`, {
151					method: "GET",
152					headers: {
153						Authorization: `Bearer ${token}`,
154					},
155				});
156	
157				if (!response.ok) {
158					return null;
159				}
160	
161				const data = await response.json();
162				if (!data || !data.userId) {
163					return null;
164				}
165				// Defense in depth: the auth server gates expiry, but never authorize a
166				// session whose access token has already expired, in case an older or
167				// misconfigured server returns one.
168				if (
169					data.accessTokenExpiresAt &&
170					new Date(data.accessTokenExpiresAt).getTime() < Date.now()
171				) {
172					return null;
173				}
174	
175				return data as McpSession;
176			} catch {
177				return null;
178			}
179		};
180	
181		const handler: McpAuthClient["handler"] = (fn) => {
182			return async (req: Request) => {
183				if (req.method === "OPTIONS") {
184					return new Response(null, { status: 204, headers: corsHeaders });
185				}
186	
187				const authHeader = req.headers.get("Authorization");
188				if (!authHeader || !authHeader.startsWith("Bearer ")) {
189					return make401Response(authURL, options.resource);
190				}
191	
192				const token = authHeader.slice(7);
193				const session = await verifyToken(token);
194				if (!session) {
195					return make401Response(authURL, options.resource);
196				}
197	
198				return fn(req, session);
199			};
200		};
201	
202		const discoveryHandler: McpAuthClient["discoveryHandler"] = () => {
203			let cachedMetadata: OAuthDiscoveryMetadata | null = null;
204			let cacheTime = 0;
205			const CACHE_TTL = 60_000;
206	
207			return async (_req: Request) => {
208				const now = Date.now();
209				if (cachedMetadata && now - cacheTime < CACHE_TTL) {
210					return Response.json(cachedMetadata, { headers: corsHeaders });
211				}
212	
213				try {
214					const response = await fetchFn(
215						`${authURL}/.well-known/oauth-authorization-server`,
216					);
217					if (!response.ok) {
218						return Response.json(
219							{ error: "Failed to fetch discovery metadata" },
220							{ status: 502, headers: corsHeaders },
221						);
222					}
223					cachedMetadata = (await response.json()) as OAuthDiscoveryMetadata;
224					cacheTime = now;
225					return Response.json(cachedMetadata, { headers: corsHeaders });
226				} catch {
227					return Response.json(
228						{ error: "Better Auth server unreachable" },
229						{ status: 502, headers: corsHeaders },
230					);
231				}
232			};
233		};
234	
235		const protectedResourceHandler: McpAuthClient["protectedResourceHandler"] = (
236			serverURL: string,
237		) => {
238			const resource = options.resource ?? new URL(serverURL).origin;
239			const metadata = {
240				resource,
241				authorization_servers: [authURL],
242				bearer_methods_supported: ["header"],
243				scopes_supported: ["openid", "profile", "email", "offline_access"],
244			};
245	
246			return async (_req: Request) => {
247				return Response.json(metadata, { headers: corsHeaders });
248			};
249		};
250	
251		const middleware: McpAuthClient["middleware"] = () => {
252			return async (
253				req: NodeLikeRequest,
254				res: NodeLikeResponse,
255				next: () => void,
256			) => {
257				const authHeader =
258					req.headers?.authorization ??
259					req.headers?.get?.("Authorization") ??
260					req.get?.("Authorization");
261	
262				if (!authHeader || !authHeader.startsWith("Bearer ")) {
263					send401Node(
264						res,
265						makeWWWAuthenticate(authURL, options.resource),
266						"Unauthorized: Authentication required",
267					);
268					return;
269				}
270	
271				const token = authHeader.slice(7);
272				const session = await verifyToken(token);
273				if (!session) {
274					send401Node(
275						res,
276						makeWWWAuthenticate(authURL, options.resource),
277						"Invalid or expired token",
278					);
279					return;
280				}
281	
282				req.mcpSession = session;
283				next();
284			};
285		};
286	
287		return {
288			verifyToken,
289			handler,
290			discoveryHandler,
291			protectedResourceHandler,
292			middleware,
293			authURL,
294		};
295	}
